package org.example;

import org.junit.jupiter.api.Test;

import net.jqwik.api.Arbitraries;
import net.jqwik.api.Arbitrary;
import net.jqwik.api.ForAll;
import net.jqwik.api.Provide;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.*;

import com.google.j2objc.annotations.Property;

import org.instancio.Instancio;
import org.instancio.Select;

class AppTest {
    @Test
    void appHasAGreeting() {
        App classUnderTest = new App();
        assertNotNull(classUnderTest.getGreeting(), "app should have a greeting");
    }

    @Test
    public void test_stuff() {
        StockItem stockItem = new StockItem();
        StockItem random1 = Instancio.create(StockItem.class);

        // Assertions
        assertThat(stockItem).usingRecursiveComparison().isNotEqualTo(random1);
    }

    static boolean isNew(StockItem stockItem) {
        return stockItem.getRegistration() == null && stockItem.getDateOfRegistration() == null;
    }

    @Property
    public void test_newVehiclesHaveNewCondition(@ForAll("newVehicles") StockItem newVehicle) {
       assertThat(isNew(newVehicle)).isFalse();
    }

    @Provide
    Arbitrary<StockItem> newVehicles() {
        return Arbitraries.ofSuppliers(() -> {
                StockItem stockItem = Instancio.create(StockItem.class);
                stockItem.setDateOfRegistration(null);
                stockItem.setRegistration(null);
                return stockItem;
            });
    }
}
